 {modal==="event"&&<Modal title={editingEvent?t("edit"):t("newEvent")} close={()=>setModal(null)}><form onSubmit={saveEvent} className="formGrid"><Field label={t("title")}><input required className="input" value={ev.title} onChange={e=>setEv({...ev,title:e.target.value})}/></Field><div className="two"><Field label={t("dueDate")}><input required type="date" className="input" value={ev.dueDate} onChange={e=>setEv({...ev,dueDate:e.target.value})}/></Field><Field label={t("time")}><input type="time" className="input" value={ev.time} onChange={e=>setEv({...ev,time:e.target.value})}/></Field></div><Toggle checked={ev.payment} setChecked={(v)=>setEv({...ev,payment:v})} label={t("payment")}/>{ev.payment&&<Field label={t("amount")}><input required type="number" min="0" className="input" value={ev.amount} onChange={e=>setEv({...ev,amount:e.target.value})}/></Field>}<Field label={t("recurrence")}><select className="input" value={ev.recurrence} onChange={e=>setEv({...ev,recurrence:e.target.value})}>{["NONE","DAILY","WEEKLY","MONTHLY","YEARLY"].map(x=><option key={x} value={x}>{t(recurrenceOptions(x) as any)}</option>)}</select></Field><div className="two"><Field label={t("before")}><input className="input" value={ev.before} onChange={e=>setEv({...ev,before:e.target.value})}/></Field><Field label={t("after")}><input className="input" value={ev.after} onChange={e=>setEv({...ev,after:e.target.value})}/></Field></div><div><label className="label">{t("membersConcerned")}</label><label className="checkRow"><input type="checkbox" checked={ev.all} onChange={e=>setEv({...ev,all:e.target.checked,ids:e.target.checked?members.map((x:any)=>x.id):[]})}/>{t("wholeGroup")}</label>{!ev.all&&members.map((x:any)=><label key={x.id} className="checkRow"><input type="checkbox" checked={ev.ids.includes(x.id)} onChange={()=>setEv({...ev,ids:ev.ids.includes(x.id)?ev.ids.filter((i:number)=>i!==x.id):[...ev.ids,x.id]})}/>{x.memberName}<small>{x.memberEmail}</small></label>)} </div><Field label={t("messageTemplate")}><textarea className="input textarea" value={ev.messageTemplate||""} onChange={e=>setEv({...ev,messageTemplate:e.target.value})}/></Field><Toggle checked={ev.notifyOwner!==false} setChecked={(v)=>setEv({...ev,notifyOwner:v})} label={t("notifyOwner")}/><div className="modalActions"><Button kind="secondary" onClick={()=>setModal(null)}>{t("cancel")}</Button><Button type="submit">{t("save")}</Button></div></form></Modal>}
 {selectedEvent&&<EventDetail event={selectedEvent} statuses={statuses} close={()=>setSelectedEvent(null)} edit={()=>{if(selectedEvent.editable===false){setToast(t("lockedEdit"));return}startEditEvent(selectedEvent);setSelectedEvent(null)}} deleteEvent={deleteEvent} generateLink={generateLink} physicalPayment={(memberId:number)=>setPhysicalPayment({type:"GROUP",reminderId:selectedEvent.id,memberId,amount:""})} markMemberDone={markMemberDone} toggleRecurrence={toggleEventRecurrence} t={t}/>}
