"use client";
import { Icon, Card, Badge, Button, IconButton, Field, Toggle, Modal, Empty, SearchBar } from "@/components/ui";
import { money, dateFr, initials, recurrenceOptions, monthGroups, monthLabel } from "@/lib/utils";
export function Groups({groups,search,setSearch,setModal,openGroup,deleteGroup,t}:any){const q=search.trim().toLowerCase();const filtered=groups.filter((g:any)=>!q||`${g.name} ${g.description||""}`.toLowerCase().includes(q));return <div className="stack"><div className="pageIntro"><p>{t("groups")}</p><Button onClick={setModal}><Icon name="plus"/> {t("newGroup")}</Button></div><SearchBar value={search} setValue={setSearch} placeholder={t("searchGroups")}/><div className="responsiveGrid">{filtered.map((g:any)=><Card key={g.id}><button type="button" className="listRow clickable" onClick={()=>openGroup(g)}><div className="avatar cyan">{initials(g.name)}</div><div className="min0 grow"><h3>{g.name}</h3><small>{g.description||"—"}</small></div></button><div className="actions tight"><Button kind="secondary" onClick={()=>openGroup(g)}>{t("open")}</Button><IconButton name="trash" onClick={()=>deleteGroup(g.id)} title={t("remove")}/></div></Card>)}{!filtered.length&&<Card><Empty text={q?t("noResults"):t("firstGroup")}/></Card>}</div></div>}
