"use client";
import { Icon, Card, Badge, Button, IconButton, Field, Toggle, Modal, Empty, SearchBar } from "@/components/ui";
import { Brand } from "@/components/common/Brand";
export function Auth({auth,setAuth,forgot,setForgot,fullName,setFullName,email,setEmail,password,setPassword,submit,forgotSubmit,loading,t}:any){
 return <div className="authPage"><div className="authCard"><div className="authHero"><Brand/><h1>{t("welcome")}</h1><p>{t("dashboardIntro")}</p><div className="authFeatures"><span><Icon name="clock"/> {t("reminders")}</span><span><Icon name="users"/> {t("groups")}</span><span><Icon name="check"/> {t("completed")}</span></div></div><div className="authForm"><div className="mobileBrand"><Brand/></div><span className="eyebrow">Échéo</span>
 {forgot ? <><h2>{t("forgotTitle")}</h2><p>{t("dashboardIntro")}</p><form onSubmit={forgotSubmit} className="formGrid"><Field label={t("email")}><input required type="email" className="input" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Button type="submit" disabled={loading}>{loading?"…":t("sendReset")}</Button></form><button className="textLink" onClick={()=>setForgot(false)}>{t("backLogin")}</button></> : <><h2>{auth==="login"?t("welcomeBack"):t("createAccount")}</h2><p>{auth==="login"?t("overview"):t("dashboardIntro")}</p><form onSubmit={submit} className="formGrid">{auth!=="login"&&<Field label={t("fullName")}><input required className="input" value={fullName} onChange={e=>setFullName(e.target.value)}/></Field>}<Field label={t("email")}><input required type="email" className="input" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label={t("password")}><input required minLength={6} type="password" className="input" value={password} onChange={e=>setPassword(e.target.value)}/></Field><Button type="submit" disabled={loading}>{loading?"…":auth==="login"?t("login"):t("register")}</Button></form>{auth==="login"&&<button className="textLink" onClick={()=>setForgot(true)}>{t("forgotPassword")}</button>}<button className="textLink" onClick={()=>setAuth(auth==="login"?"register":"login")}>{auth==="login"?t("noAccount"):t("alreadyAccount")}</button></>}
 </div></div></div>}

